<script setup lang="ts">
import { ArrowLeft, Save } from '@lucide/vue'
definePageMeta({middleware:'customer'})
const {data,refresh}=await useFetch<{profile:{firstName:string;lastName:string;phone:string;whatsapp:string|null;email:string|null}}>('/api/account/appointments',{key:'account-appointments'})
const form=reactive({firstName:'',lastName:'',phone:'',whatsapp:'',email:''}),busy=ref(false),message=ref(''),failure=ref('')
watchEffect(()=>{if(data.value?.profile)Object.assign(form,{...data.value.profile,whatsapp:data.value.profile.whatsapp||'',email:data.value.profile.email||''})})
async function save(){busy.value=true;message.value='';failure.value='';try{await $fetch('/api/account/profile',{method:'PATCH',body:form});message.value='Votre profil est enregistré.';await refresh()}catch(error){failure.value=(error as {data?:{statusMessage?:string}})?.data?.statusMessage||'Le profil n’a pas pu être mis à jour.'}finally{busy.value=false}}
useSeoMeta({title:'Mon profil — Votre onglerie',robots:'noindex,nofollow'})
</script>
<template><div class="container-narrow profile-page"><NuxtLink class="back-link" to="/mon-compte"><ArrowLeft :size="14"/> Mon compte</NuxtLink><div class="profile-card surface-card"><span class="eyebrow">Mes coordonnées</span><h1 class="display">Mon profil.</h1><form @submit.prevent="save"><label class="form-field"><span>Prénom</span><input v-model="form.firstName" class="form-control" required minlength="2" maxlength="80"></label><label class="form-field"><span>Nom</span><input v-model="form.lastName" class="form-control" required minlength="2" maxlength="80"></label><label class="form-field"><span>Téléphone</span><input v-model="form.phone" class="form-control" type="tel" required></label><label class="form-field"><span>WhatsApp (facultatif)</span><input v-model="form.whatsapp" class="form-control" type="tel"></label><label class="form-field"><span>E-mail</span><input v-model="form.email" class="form-control" type="email"></label><button class="btn btn-primary" type="submit" :disabled="busy">{{busy?'Enregistrement…':'Enregistrer'}} <Save :size="15"/></button><p v-if="message" class="success" role="status">{{message}}</p><p v-if="failure" class="error" role="alert">{{failure}}</p></form></div></div></template>
<style scoped>.profile-page{padding:4rem 0}.back-link{display:inline-flex;gap:.4rem;margin-bottom:1rem;color:var(--muted);font-size:.68rem}.profile-card{padding:2rem}.profile-card h1{margin:.5rem 0 1.5rem;font-size:4rem}.profile-card form{display:grid;gap:1rem}.profile-card label{display:grid;gap:.4rem}.profile-card label span{font-size:.7rem;font-weight:700}.error{color:#943d48}.success{color:#2f674c}</style>
